import Foundation

/// Offline airport lookup, in two layers.
///
/// * **Curated** (`Resources/airports.json`, ~110 airports): terminal notes and
///   researched minimum connection times. This is what the Airports tab lists.
/// * **World** (`Resources/airports-world.json`, ~7,900 airports): every
///   IATA-coded airport with a position and an IANA time zone, nothing more.
///   Generated by `scripts/build_world_airports.py`.
///
/// `airport(iata:)` consults curated first, then world. The world layer exists
/// because a miss here is never just a missing label: a flight out of John
/// Wayne (SNA) lost its route map, its mileage, its local times, and its
/// traffic map quietly anchored on the *other* end of the route. Anything the
/// app needs to draw or time an airport must resolve through this method.
///
/// Kept as a plain singleton — the data is static and needed synchronously all
/// over the UI, including from inside `Canvas` frames.
final class AirportDatabase {
    static let shared = AirportDatabase()

    /// The curated list, sorted by code. Deliberately *not* the world list:
    /// eight thousand rows is a phone book, not a browsing experience. Search
    /// reaches the world list instead.
    let airports: [Airport]
    private let byIATA: [String: Airport]

    /// Decoded on first miss rather than at launch: most sessions only ever
    /// touch curated airports, and there's no reason to parse 780 KB of JSON
    /// to draw them. Locked because lookups also come from off the main actor
    /// (the forecaster, notification scheduling), and two of them racing the
    /// first decode must not both build the table.
    private var worldStorage: [String: Airport]?
    private let worldLock = NSLock()

    private init() {
        airports = Self.decodeCurated().sorted { $0.iata < $1.iata }
        byIATA = Dictionary(airports.map { ($0.iata, $0) }, uniquingKeysWith: { first, _ in first })
    }

    /// Total airports the app can place on a map — for Settings.
    var resolvableCount: Int {
        world.keys.reduce(into: byIATA.count) { count, iata in
            if byIATA[iata] == nil { count += 1 }
        }
    }

    func airport(iata: String) -> Airport? {
        let code = iata.trimmingCharacters(in: .whitespaces).uppercased()
        guard !code.isEmpty else { return nil }
        return byIATA[code] ?? world[code]
    }

    /// Empty query → the curated list. Otherwise curated matches first (they
    /// carry the richer detail page), then the world list, exact IATA hits on
    /// top within each. Capped, because "a" matches thousands of airport names.
    func search(_ query: String, limit: Int = 60) -> [Airport] {
        let q = query.trimmingCharacters(in: .whitespaces)
        guard !q.isEmpty else { return airports }
        let upper = q.uppercased()

        func matches(_ airport: Airport) -> Bool {
            airport.iata.hasPrefix(upper)
                || airport.icao.hasPrefix(upper)
                || airport.name.localizedCaseInsensitiveContains(q)
                || airport.city.localizedCaseInsensitiveContains(q)
        }
        func rank(_ a: Airport, _ b: Airport) -> Bool {
            (a.iata == upper ? 0 : 1, a.iata) < (b.iata == upper ? 0 : 1, b.iata)
        }

        let curated = airports.filter(matches).sorted(by: rank)
        let worldHits = world.values
            .filter { byIATA[$0.iata] == nil && matches($0) }
            .sorted(by: rank)
        return Array((curated + worldHits).prefix(limit))
    }

    // MARK: - Loading

    private var world: [String: Airport] {
        worldLock.lock()
        defer { worldLock.unlock() }
        if let worldStorage { return worldStorage }
        let loaded = Self.decodeWorld()
        worldStorage = loaded
        return loaded
    }

    private static func decodeCurated() -> [Airport] {
        guard let url = Bundle.main.url(forResource: "airports", withExtension: "json"),
              let data = try? Data(contentsOf: url),
              let decoded = try? JSONDecoder().decode([Lenient<Airport>].self, from: data)
        else { return [] }
        return decoded.compactMap(\.value)
    }

    /// Rows are positional arrays — `[iata, icao, name, city, country, lat,
    /// lon, tz]` — which keeps the file at roughly half the size of keyed
    /// objects. One malformed row is skipped, never fatal.
    private static func decodeWorld() -> [String: Airport] {
        guard let url = Bundle.main.url(forResource: "airports-world", withExtension: "json"),
              let data = try? Data(contentsOf: url),
              let rows = try? JSONDecoder().decode([Lenient<WorldRow>].self, from: data)
        else { return [:] }
        var result: [String: Airport] = [:]
        result.reserveCapacity(rows.count)
        for row in rows {
            guard let airport = row.value?.airport else { continue }
            result[airport.iata] = airport
        }
        return result
    }

    private struct WorldRow: Decodable {
        var airport: Airport

        init(from decoder: Decoder) throws {
            var row = try decoder.unkeyedContainer()
            let iata = try row.decode(String.self)
            let icao = try row.decode(String.self)
            let name = try row.decode(String.self)
            let city = try row.decode(String.self)
            let country = try row.decode(String.self)
            let lat = try row.decode(Double.self)
            let lon = try row.decode(Double.self)
            let tz = try row.decode(String.self)
            airport = Airport(iata: iata,
                              icao: icao,
                              name: name,
                              city: city,
                              country: country,
                              lat: lat,
                              lon: lon,
                              tz: tz,
                              mctDomestic: Airport.typicalMCTDomestic,
                              mctInternational: Airport.typicalMCTInternational,
                              terminals: nil,
                              isFromWorldList: true)
        }
    }
}
